// 1. Validation and Initialization
if (qs_input.current_q_bi == NULL || qs_input.target_q_bi == NULL) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.settled = FALSE32;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = FALSE32;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

adcs_quat_t current_norm, target_norm;
if (adcs_quat_normalize(qs_input.current_q_bi, &current_norm) != ADCS_OK ||
    adcs_quat_normalize(qs_input.target_q_bi, &target_norm) != ADCS_OK) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.settled = FALSE32;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = FALSE32;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

// Check config constraints
if (!isfinite(qs_config.max_rate_rad_cycle) || qs_config.max_rate_rad_cycle <= 0.0 ||
    qs_config.max_rate_rad_cycle > PI ||
    !isfinite(qs_config.max_accel_rad_cycle2) || qs_config.max_accel_rad_cycle2 <= 0.0 ||
    !isfinite(qs_config.settle_angle_rad) || qs_config.settle_angle_rad < 0.0 ||
    !isfinite(qs_config.settle_rate_rad_cycle) || qs_config.settle_rate_rad_cycle < 0.0 ||
    qs_config.settle_rate_rad_cycle > qs_config.max_rate_rad_cycle ||
    !isfinite(qs_config.settle_cycles) || qs_config.settle_cycles < 1 ||
    qs_config.settle_cycles > 20) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.settled = FALSE32;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = FALSE32;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

int reversal_reset = FALSE32;
qs_mode_t final_mode = qs_state.mode;

// 2. Relative Quaternion and Axis/Angle Calculation
adcs_quat_t rel_q = adcs_quat_multiply(&target_norm, &adcs_quat_conjugate(&current_norm));

// Ensure shortest path
if (rel_q.w < 0.0) {
    rel_q.w = -rel_q.w;
    rel_q.x = -rel_q.x;
    rel_q.y = -rel_q.y;
    rel_q.z = -rel_q.z;
}

double error_angle_rad = 2.0 * acos(rel_q.w);
if (error_angle_rad < 0.0) error_angle_rad = -error_angle_rad;

adcs_vec3_t slew_axis_body;
double sin_half = sqrt(1.0 - rel_q.w * rel_q.w);

if (sin_half < ADCS_EPS_QUAT) {
    slew_axis_body = (adcs_vec3_t){0, 0, 0};
} else {
    slew_axis_body.x = rel_q.x / sin_half;
    slew_axis_body.y = rel_q.y / sin_half;
    slew_axis_body.z = rel_q.z / sin_half;
}

// 3. Reversal Reset Logic (Only if not in HOLD/Fault)
if (qs_state.mode != QS_HOLD && qs_state.mode != QS_FAULT && qs_state.axis_valid) {
    double dot = adcs_vec3_dot(&slew_axis_body, &qs_state.previous_axis);
    if (dot < 0.0) {
        qs_state.commanded_rate_rad_cycle = 0.0;
        reversal_reset = TRUE32;
    }
}

// 4. Rate Planning (Skip if in HOLD)
if (qs_state.mode == QS_HOLD) {
    qs_state.commanded_rate_rad_cycle = 0.0;
} else {
    double braking_rate = sqrt(2.0 * qs_config.max_accel_rad_cycle2 * error_angle_rad);
    double target_rate = Minx(qs_config.max_rate_rad_cycle, braking_rate);
    double delta_rate = qs_config.max_accel_rad_cycle2;

    if (qs_state.commanded_rate_rad_cycle < target_rate) {
        qs_state.commanded_rate_rad_cycle += delta_rate;
        if (qs_state.commanded_rate_rad_cycle > target_rate) {
            qs_state.commanded_rate_rad_cycle = target_rate;
        }
        final_mode = QS_ACCEL;
    } else if (qs_state.commanded_rate_rad_cycle > target_rate) {
        qs_state.commanded_rate_rad_cycle -= delta_rate;
        if (qs_state.commanded_rate_rad_cycle < target_rate) {
            qs_state.commanded_rate_rad_cycle = target_rate;
        }
        final_mode = QS_DECEL;
    } else {
        final_mode = QS_CRUISE;
    }

    if (qs_state.commanded_rate_rad_cycle < 0.0) {
        qs_state.commanded_rate_rad_cycle = 0.0;
    }
}

// 5. Apply Step
double applied_step = Minx(qs_state.commanded_rate_rad_cycle, error_angle_rad);

adcs_quat_t dq;
double half_step = applied_step * 0.5;
dq.w = cos(half_step);
double s = sin(half_step);
dq.x = slew_axis_body.x * s;
dq.y = slew_axis_body.y * s;
dq.z = slew_axis_body.z * s;

adcs_quat_t next_q = adcs_quat_multiply(&dq, &current_norm);

// Update state history
if (qs_state.mode != QS_HOLD) {
    qs_state.previous_axis = slew_axis_body;
    qs_state.axis_valid = TRUE32;
}

// 6. Settling Logic
unint32 settled = FALSE32;

if (qs_state.mode != QS_HOLD) {
    if (error_angle_rad <= qs_config.settle_angle_rad && 
